cat > /tmp/fuzz.mjs <<'EOF'
// Generate random domain strings from assorted Unicode ranges
const ranges = [
  [0x61, 0x7a],   // ascii lower
  [0x30, 0x39],   // digits
  [0xe0, 0xff],   // latin-1 supplement
  [0x100, 0x17f], // latin extended
  [0x370, 0x3ff], // greek
  [0x400, 0x45f], // cyrillic
  [0x5d0, 0x5ea], // hebrew
  [0x620, 0x64a], // arabic
  [0x3040, 0x30ff], // kana
  [0x4e00, 0x4eff], // CJK
  [0xc00, 0xc7f], // telugu
];
let seed = 12345;
const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
const labels = [];
for (let i = 0; i < 120; i++) {
  const len = 1 + Math.floor(rnd() * 8);
  let l = '';
  for (let j = 0; j < len; j++) {
    const r = ranges[Math.floor(rnd() * ranges.length)];
    l += String.fromCodePoint(r[0] + Math.floor(rnd() * (r[1] - r[0])));
  }
  labels.push(l);
}
for (let i = 0; i < labels.length; i += 2) {
  console.log(labels[i] + '.' + (labels[i + 1] || 'com'));
}
EOF
node /tmp/fuzz.mjs > /tmp/fuzz_cases.txt
pass=0; fail=0
while IFS= read -r d; do
  exp=$(/workspace/dataset/test1_executable --domain "$d" 2>/dev/null); erc=$?
  act=$(node /output/test1.mjs --domain "$d" 2>/dev/null); arc=$?
  if [[ "$exp" == "$act" && "$erc" == "$arc" ]]; then pass=$((pass+1)); else
    fail=$((fail+1)); echo "FAIL: $d"; echo " exe(rc=$erc): $exp" | head -5; echo " got(rc=$arc): $act" | head -5
  fi
done < /tmp/fuzz_cases.txt
echo "FUZZ PASS=$pass FAIL=$fail"

