// Black-box discovery of IDNA2008 character tables by probing the executable.
import { execFile } from 'node:child_process';
import { writeFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test1_executable';

function run(domain) {
  return new Promise((resolve) => {
    execFile(EXE, ['--domain', domain], { maxBuffer: 4 * 1024 * 1024 }, (err, stdout, stderr) => {
      resolve({ stderr: stderr || '', ok: !err });
    });
  });
}

async function pool(items, workerFn, concurrency = 10) {
  let idx = 0;
  async function worker() {
    while (idx < items.length) {
      const item = items[idx++];
      await workerFn(item);
      if (idx % 200 === 0) console.error(`progress ${idx}/${items.length}`);
    }
  }
  await Promise.all(Array.from({ length: concurrency }, worker));
}

function toRanges(cps) {
  const sorted = [...new Set(cps)].sort((a, b) => a - b);
  const ranges = [];
  for (const cp of sorted) {
    const last = ranges[ranges.length - 1];
    if (last && cp === last[1] + 1) last[1] = cp;
    else ranges.push([cp, cp]);
  }
  return ranges;
}

// ---------- Job A: DISALLOWED codepoints among PVALID-category chars ----------
const PVALID_RE = /[\p{Ll}\p{Lo}\p{Lm}\p{Mn}\p{Mc}\p{Nd}]/u;
async function jobA() {
  const cands = [];
  for (let cp = 0x80; cp <= 0x10ffff; cp++) {
    if (cp >= 0xd800 && cp <= 0xdfff) continue;
    const ch = String.fromCodePoint(cp);
    if (!PVALID_RE.test(ch)) continue;
    if (ch.normalize('NFC') !== ch) continue;
    cands.push(cp);
  }
  console.error('jobA candidates:', cands.length);
  const disallowed = [];
  const BATCH = 40;
  const batches = [];
  for (let i = 0; i < cands.length; i += BATCH) batches.push(cands.slice(i, i + BATCH));
  await pool(batches, async (batch) => {
    let current = batch;
    let guard = 0;
    while (current.length > 0 && guard++ < 100) {
      const label = '7' + current.map((cp) => String.fromCodePoint(cp)).join('7');
      const { stderr } = await run(label + '.x');
      const m = stderr.match(/InvalidCodepoint: Codepoint U\+([0-9A-F]+) at position/);
      if (m) {
        const cp = parseInt(m[1], 16);
        if (!current.includes(cp)) {
          console.error('unexpected cp', m[1], 'stderr:', stderr.split('\n').slice(-3).join(' | '));
          break;
        }
        disallowed.push(cp);
        current = current.filter((c) => c !== cp);
        continue;
      }
      if (/InvalidCodepoint(Context)?:/.test(stderr)) {
        console.error('unexpected context error:', stderr.split('\n').slice(-3).join(' | '));
      }
      break; // any other outcome: whole batch is valid
    }
  });
  writeFileSync('/tmp/disallowed.json', JSON.stringify(toRanges(disallowed)));
  console.error('jobA done, disallowed:', disallowed.length);
}

// ---------- Job B: joining types for cursive script ranges ----------
const JOIN_RANGES = [
  [0x600, 0x8ff], [0x1800, 0x18ff], [0xa840, 0xa87f],
  [0x10a00, 0x10a5f], [0x10ac0, 0x10aff], [0x10b80, 0x10baf],
  [0x10d00, 0x10d3f], [0x10e80, 0x10ebf], [0x10f30, 0x10fdf],
];
async function jobB() {
  const cps = [];
  for (const [lo, hi] of JOIN_RANGES) for (let cp = lo; cp <= hi; cp++) cps.push(cp);
  const typeL = [], typeR = [], typeD = [];
  const ZWNJ = '‌';
  await pool(cps, async (cp) => {
    const ch = String.fromCodePoint(cp);
    // left test: ch + ZWNJ + beh  => passes iff ch in {L, D}
    const l = await run(ch + ZWNJ + 'ب.x');
    const lPass = !l.stderr.includes('Unknown codepoint adjacent to joiner') && !/InvalidCodepoint/.test(l.stderr);
    // right test: beh + ZWNJ + ch => passes iff ch in {R, D}
    const r = await run('ب' + ZWNJ + ch + '.x');
    const rPass = !r.stderr.includes('Unknown codepoint adjacent to joiner') && !/InvalidCodepoint/.test(r.stderr);
    if (lPass && rPass) typeD.push(cp);
    else if (lPass) typeL.push(cp);
    else if (rPass) typeR.push(cp);
  });
  writeFileSync('/tmp/joining.json', JSON.stringify({ L: toRanges(typeL), R: toRanges(typeR), D: toRanges(typeD) }));
  console.error('jobB done: L=%d R=%d D=%d', typeL.length, typeR.length, typeD.length);
}

// ---------- Job C: virama (canonical combining class 9) codepoints ----------
const MARK_RE = /[\p{Mn}\p{Mc}]/u;
async function jobC() {
  const cps = [];
  for (let cp = 0x80; cp <= 0x10ffff; cp++) {
    if (cp >= 0xd800 && cp <= 0xdfff) continue;
    if (MARK_RE.test(String.fromCodePoint(cp))) cps.push(cp);
  }
  console.error('jobC candidates:', cps.length);
  const viramas = [];
  const ZWJ = '‍';
  await pool(cps, async (cp) => {
    const { ok, stderr } = await run('7' + String.fromCodePoint(cp) + ZWJ + '7.x');
    if (ok) viramas.push(cp);
    else if (!stderr.includes('Unknown codepoint adjacent to joiner')) {
      // disallowed / NFC errors: not usable viramas in valid labels anyway
    }
  });
  writeFileSync('/tmp/virama.json', JSON.stringify(toRanges(viramas)));
  console.error('jobC done, viramas:', viramas.length);
}

await Promise.all([jobA(), jobB(), jobC()]);
console.error('ALL DONE');

