  [0x10a00, 0x10a5f], [0x10ac0, 0x10aff], [0x10b80, 0x10baf],
  [0x10d00, 0x10d3f], [0x10e80, 0x10ebf], [0x10f30, 0x10fdf],
];
async function jobB() {
  const cps = [];
  for (const [lo, hi] of JOIN_RANGES) for (let cp = lo; cp <= hi; cp++) cps.push(cp);
  const typeL = [], typeR = [], typeD = [];
  const ZWNJ = '‌';
  await pool(cps, async (cp) => {
    const ch = String.fromCodePoint(cp);
    // left test: ch + ZWNJ + beh  => passes iff ch in {L, D}
    const l = await run(ch + ZWNJ + 'ب.x');
    const lPass = !l.stderr.includes('Unknown codepoint adjacent to joiner') && !/InvalidCodepoint/.test(l.stderr);
    // right test: beh + ZWNJ + ch => passes iff ch in {R, D}
    const r = await run('ب' + ZWNJ + ch + '.x');
    const rPass = !r.stderr.includes('Unknown codepoint adjacent to joiner') && !/InvalidCodepoint/.test(r.stderr);
    if (lPass && rPass) typeD.push(cp);
    else if (lPass) typeL.push(cp);
    else if (rPass) typeR.push(cp);
  });
  writeFileSync('/tmp/joining.json', JSON.stringify({ L: toRanges(typeL), R: toRanges(typeR), D: toRanges(typeD) }));
  console.error('jobB done: L=%d R=%d D=%d', typeL.length, typeR.length, typeD.length);
}

// ---------- Job C: virama (canonical combining class 9) codepoints ----------
const MARK_RE = /[\p{Mn}\p{Mc}]/u;
async function jobC() {
  const cps = [];
  for (let cp = 0x80; cp <= 0x10ffff; cp++) {
    if (cp >= 0xd800 && cp <= 0xdfff) continue;
    if (MARK_RE.test(String.fromCodePoint(cp))) cps.push(cp);
  }
  console.error('jobC candidates:', cps.length);
  const viramas = [];
  const ZWJ = '‍';
  await pool(cps, async (cp) => {
    const { ok, stderr } = await run('7' + String.fromCodePoint(cp) + ZWJ + '7.x');
    if (ok) viramas.push(cp);
    else if (!stderr.includes('Unknown codepoint adjacent to joiner')) {
      // disallowed / NFC errors: not usable viramas in valid labels anyway
    }
  });
  writeFileSync('/tmp/virama.json', JSON.stringify(toRanges(viramas)));
  console.error('jobC done, viramas:', viramas.length);
}

await Promise.all([jobA(), jobB(), jobC()]);
console.error('ALL DONE');

