// RFC 5892 Appendix A.1: contextual rule for ZWNJ (U+200C) / ZWJ (U+200D).
// chars is the label as an array of code points, pos is the joiner index.
function validContextj(chars, pos) {
  const cp = chars[pos].codePointAt(0);
  const joiningType = (ch) => {
    const v = ch.codePointAt(0);
    if (inRanges(JOINING_L, v)) return 'L';
    if (inRanges(JOINING_R, v)) return 'R';
    if (inRanges(JOINING_D, v)) return 'D';
    if (/[\p{Mn}\p{Me}]/u.test(ch)) return 'T';
    return 'U';
  };
  if (cp === 0x200c) {
    let ok = false;
    for (let i = pos - 1; i >= 0; i--) {
      const jt = joiningType(chars[i]);
      if (jt === 'T') continue;
      if (jt === 'L' || jt === 'D') ok = true;
      break;
    }
    if (!ok) return false;
    ok = false;
    for (let i = pos + 1; i < chars.length; i++) {
      const jt = joiningType(chars[i]);
      if (jt === 'T') continue;
      if (jt === 'R' || jt === 'D') ok = true;
      break;
    }
    return ok;
  }
  // U+200D ZWJ: preceding character must be a virama (ccc = 9)
  if (pos > 0 && inRanges(VIRAMA, chars[pos - 1].codePointAt(0))) return true;
  return false;
}

// RFC 5892 Appendix A: contextual rules for CONTEXTO codepoints.
function validContexto(chars, pos) {
  const cp = chars[pos].codePointAt(0);
  if (cp === 0x00b7) {
    // Greek middle dot rule: between two 'l' (U+006C)
    return pos > 0 && pos < chars.length - 1 && chars[pos - 1] === 'l' && chars[pos + 1] === 'l';
  }
  if (cp === 0x0375) {
    // followed by a Greek-script character
    return pos < chars.length - 1 && GREEK_RE.test(chars[pos + 1]);
  }
  if (cp === 0x05f3) {
    // preceded by a Hebrew-script character
    return pos > 0 && HEBREW_RE.test(chars[pos - 1]);
  }
  if (cp === 0x30fb) {
    // label contains Hiragana, Katakana or Han
    return chars.some((ch) => KANA_HAN_RE.test(ch));
  }
  return false;
}

const NSM_RE = /[\p{Mn}\p{Me}]/u;
const LETTER_RE = /\p{L}/u;
const R_SCRIPT_RE = /[\p{Script=Hebrew}\p{Script=Nko}\p{Script=Samaritan}\p{Script=Adlam}]/u;
const AL_SCRIPT_RE =
  /[\p{Script=Arabic}\p{Script=Syriac}\p{Script=Thaana}\p{Script=Mandaic}\p{Script=Manichaean}\p{Script=Hanifi_Rohingya}\p{Script=Yezidi}\p{Script=Old_Uyghur}\p{Script=Sogdian}\p{Script=Chorasmian}\p{Script=Elymaic}\p{Script=Psalter_Pahlavi}]/u;

// Approximate Unicode bidi class. ES/CS/ET/ON/BN behave identically in the
// RFC 5893 rules applied here, so they are lumped together as 'ON'.
function bidiClass(ch) {
  const cp = ch.codePointAt(0);
  if (NSM_RE.test(ch)) return 'NSM';
  if (cp >= 0x30 && cp <= 0x39) return 'EN';
  if ((cp >= 0x660 && cp <= 0x669) || (cp >= 0x6f0 && cp <= 0x6f9)) return 'AN';
  if (cp === 0x5f3) return 'R';
  if (LETTER_RE.test(ch)) {
    if (R_SCRIPT_RE.test(ch)) return 'R';
    if (AL_SCRIPT_RE.test(ch)) return 'AL';
    return 'L';
  }
  return 'ON';
}

// RFC 5893 bidi rules, as applied by the Python idna package.
function checkBidi(label) {
  const chars = Array.from(label);
  const dirs = chars.map(bidiClass);
  if (!dirs.some((d) => d === 'R' || d === 'AL' || d === 'AN')) return;

  const first = dirs[0];
  let rtl;
  if (first === 'R' || first === 'AL') rtl = true;
  else if (first === 'L') rtl = false;
  else {
    throw new IDNABidiError(
      `First codepoint in label ${pyStrRepr(label)} must be directionality L, R or AL`
    );
  }

  let validEnding = false;
  let numberType = null;
  for (let i = 0; i < dirs.length; i++) {
    const d = dirs[i];
    if (rtl) {
      if (!['R', 'AL', 'AN', 'EN', 'NSM', 'ON'].includes(d)) {
        throw new IDNABidiError(
          `Invalid direction for codepoint at position ${i + 1} in a right-to-left label`
        );
      }
      if (d === 'R' || d === 'AL' || d === 'EN' || d === 'AN') validEnding = true;
      else if (d !== 'NSM') validEnding = false;
      if (d === 'AN' || d === 'EN') {
        if (numberType === null) numberType = d;
        else if (numberType !== d) {
          throw new IDNABidiError('Can not mix numeral types in a right-to-left label');
        }
      }
    } else {
      if (!['L', 'EN', 'NSM', 'ON'].includes(d)) {
        throw new IDNABidiError(
          `Invalid direction for codepoint at position ${i + 1} in a left-to-right label`
        );
      }
      if (d === 'L' || d === 'EN') validEnding = true;
      else if (d !== 'NSM') validEnding = false;
    }
  }
  if (!validEnding) {
    throw new IDNABidiError('Label ends with illegal codepoint directionality');
  }
}

export function checkLabel(label) {
  if (label.length === 0) {
    throw new IDNAError('Empty Label');
  }
  if (label.normalize('NFC') !== label) {
    throw new IDNAError('Label must be in Normalization Form C');
  }
  if (label.slice(2, 4) === '--') {
    throw new IDNAError('Label has disallowed hyphens in 3rd and 4th position');
  }
  if (label.startsWith('-') || label.endsWith('-')) {
    throw new IDNAError('Label must not start or end with a hyphen');
  }
  const chars = Array.from(label);
  if (COMBINING_RE.test(chars[0])) {
    throw new IDNAError('Label begins with an illegal combining character');
  }
  for (let pos = 0; pos < chars.length; pos++) {
    const ch = chars[pos];
    const cp = ch.codePointAt(0);
    if (CP_CONTEXTJ.has(cp)) {
      if (!validContextj(chars, pos)) {
        throw new IDNAError(
          `Unknown codepoint adjacent to joiner ${unot(cp)} at position ${pos + 1} in ${pyStrRepr(label)}`
        );
      }
      continue;
    }
    if (CP_CONTEXTO.has(cp)) {
      if (!validContexto(chars, pos)) {
        throw new InvalidCodepointContext(
          `Codepoint ${unot(cp)} not allowed at position ${pos + 1} in ${pyStrRepr(label)}`
        );
      }
      continue;
    }
    if (PVALID_RE.test(ch) && !inRanges(DISALLOWED, cp)) continue;
    throw new InvalidCodepoint(
      `Codepoint ${unot(cp)} at position ${pos + 1} of ${pyStrRepr(label)} not allowed`
    );
  }
  checkBidi(label);
}

