          `Invalid direction for codepoint at position ${i + 1} in a left-to-right label`
        );
      }
      if (d === 'L' || d === 'EN') validEnding = true;
      else if (d !== 'NSM') validEnding = false;
    }
  }
  if (!validEnding) {
    throw new IDNABidiError('Label ends with illegal codepoint directionality');
  }
}

export function checkLabel(label) {
  if (label.length === 0) {
    throw new IDNAError('Empty Label');
  }
  if (label.normalize('NFC') !== label) {
    throw new IDNAError('Label must be in Normalization Form C');
  }
  if (label.slice(2, 4) === '--') {
    throw new IDNAError('Label has disallowed hyphens in 3rd and 4th position');
  }
  if (label.startsWith('-') || label.endsWith('-')) {
    throw new IDNAError('Label must not start or end with a hyphen');
  }
  const chars = Array.from(label);
  if (COMBINING_RE.test(chars[0])) {
    throw new IDNAError('Label begins with an illegal combining character');
  }
  for (let pos = 0; pos < chars.length; pos++) {
    const ch = chars[pos];
    const cp = ch.codePointAt(0);
    if (CP_CONTEXTJ.has(cp)) {
      if (!validContextj(chars, pos)) {
        throw new IDNAError(
          `Unknown codepoint adjacent to joiner ${unot(cp)} at position ${pos + 1} in ${pyStrRepr(label)}`
        );
      }
      continue;
    }
    if (CP_CONTEXTO.has(cp)) {
      if (!validContexto(chars, pos)) {
        throw new InvalidCodepointContext(
          `Codepoint ${unot(cp)} not allowed at position ${pos + 1} in ${pyStrRepr(label)}`
        );
      }
      continue;
    }
    if (PVALID_RE.test(ch) && !inRanges(DISALLOWED, cp)) continue;
    throw new InvalidCodepoint(
      `Codepoint ${unot(cp)} at position ${pos + 1} of ${pyStrRepr(label)} not allowed`
    );
  }
  checkBidi(label);
}

args.command:
node -e '
const fs = require("fs");
const d = JSON.parse(fs.readFileSync("/tmp/disallowed.json","utf8"));
const j = JSON.parse(fs.readFileSync("/tmp/joining.json","utf8"));
const v = JSON.parse(fs.readFileSync("/tmp/virama.json","utf8"));
const fmt = (ranges) => {
  const rows = [];
  for (let i = 0; i < ranges.length; i += 6) {
    rows.push("  " + ranges.slice(i, i + 6).map(([a,b]) => `[0x${a.toString(16)},0x${b.toString(16)}]`).join(",") + ",");
  }
  return rows.join("\n");
};
const header = `// IDNA2008 character tables, derived black-box from the reference
// implementation. Each table is a sorted list of inclusive codepoint ranges.
`;
const out = `${header}
// DISALLOWED: codepoints in PVALID general categories that IDNA2008 rejects.
export const DISALLOWED = [
${fmt(d)}
];

// Joining types (RFC 5892 Appendix A.1) for cursive scripts.
export const JOINING_L = [
${fmt(j.L)}
];
export const JOINING_R = [
${fmt(j.R)}
];
export const JOINING_D = [
${fmt(j.D)}
];

// VIRAMA: codepoints with canonical combining class 9 (RFC 5892 Appendix A.2).
export const VIRAMA = [
${fmt(v)}
];

// Binary search of a codepoint in a sorted inclusive-range list.
export function inRanges(ranges, cp) {
  let lo = 0;
  let hi = ranges.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (cp < ranges[mid][0]) hi = mid - 1;
    else if (cp > ranges[mid][1]) lo = mid + 1;
    else return true;
  }
  return false;
}
`;
fs.writeFileSync("/output/lib/idna_tables.mjs", out);
console.log("ranges:", d.length, j.L.length, j.R.length, j.D.length, v.length);
'

