args.command:
cat > /tmp/fuzz2.mjs <<'EOF'
// Random domains weighted toward tricky ranges: RTL scripts, combining marks,
// joiners, letterlike symbols, Greek/Cyrillic lookalikes.
const pools = [
  [0x61, 0x7a], [0x30, 0x39],
  [0xc0, 0xff], [0x100, 0x17f], [0x180, 0x24f],
  [0x370, 0x3ff], [0x400, 0x4ff],
  [0x590, 0x5ff], [0x600, 0x6ff], [0x750, 0x77f],
  [0x900, 0x97f], [0xc00, 0xc7f],
  [0x3040, 0x30ff], [0x4e00, 0x4eff],
  [0x2b0, 0x2ff], [0x1d00, 0x1d7f], [0x2000, 0x206f],
];
let seed = 987654321;
const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
const out = [];
for (let i = 0; i < 300; i++) {
  const nLabels = 1 + Math.floor(rnd() * 2);
  const labels = [];
  for (let l = 0; l < nLabels; l++) {
    const len = 1 + Math.floor(rnd() * 6);
    let s = '';
    for (let j = 0; j < len; j++) {
      const p = pools[Math.floor(rnd() * pools.length)];
      s += String.fromCodePoint(p[0] + Math.floor(rnd() * (p[1] - p[0])));
    }
    labels.push(s);
  }
  out.push(labels.join('.'));
}
console.log(out.join('\n'));
EOF
node /tmp/fuzz2.mjs > /tmp/fuzz2_cases.txt
cat > /tmp/fuzzrun.mjs <<'EOF'
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
const cases = readFileSync(process.argv[2], 'utf8').split('\n').filter(Boolean);
let pass = 0, fail = 0;
for (const d of cases) {
  let eo, ec, ao, ac;
  try { eo = execFileSync('/workspace/dataset/test1_executable', ['--domain', d], {encoding:'utf8'}); ec = 0; }
  catch (e) { eo = e.stdout || ''; ec = e.status; }
  try { ao = execFileSync('node', ['/output/test1.mjs', '--domain', d], {encoding:'utf8'}); ac = 0; }
  catch (e) { ao = e.stdout || ''; ac = e.status; }
  if (eo === ao && ec === ac) pass++;
  else {
    fail++;
    if (fail <= 12) {
      console.log('FAIL', JSON.stringify(d), 'exe_rc=' + ec, 'got_rc=' + ac);
      console.log('  exe:', JSON.stringify(eo.split('\n')[0]));
      console.log('  got:', JSON.stringify(ao.split('\n')[0]));
    }
  }
}
console.log(`FUZZ PASS=${pass} FAIL=${fail}`);
EOF
node /tmp/fuzzrun.mjs /tmp/fuzz2_cases.txt

